import React from "react";
import { Token } from "../eagles";
import { useParams } from "react-router-dom";
import { useState } from "react";

type paramsType = {
  gameId: string;
};

type GameContextType = {
  gameTokens: Token[];
  setGameTokens: React.Dispatch<React.SetStateAction<Token[]>>;
};

const eaglesContext = React.createContext<GameContextType>({
  gameTokens: [],
  setGameTokens: () => {},
});

export const EaglesContextProvider = (props: React.PropsWithChildren<{}>) => {
  const { gameId } = useParams<paramsType>();
  const [gameTokens, setGameTokens] = useState<Token[]>([]);
  return (
    <eaglesContext.Provider value={{ gameTokens, setGameTokens }}>
      {props.children}
    </eaglesContext.Provider>
  );
};

export const useEaglesContext = () => {
  const context = React.useContext(eaglesContext);
  if (context === undefined) {
    throw new Error("useEagleContext must be used within an EaglesContextProvider");
  }
  return context;
};


