  board_ = std::move(Move(position));
  board_.get_move(move);
  if (board_.illlegal()) return *this;
  board_.make_move(move);
  return *this;
}

std::vector<std::string> MoveGenerator::generate_moves() {
  std::vector<std::string> generated_moves;
  for (auto move : board_.generate()) {
    board_.get_move(move);
    if (board_.illlegal()) continue;
    board_.make_move(move);
    generated_moves.push_back(move);
    board_.unmake_move();
  }
  return generated_moves;
}


